window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[353]={"id":"353","numero":353,"titre":"Risque et conduite suicidaire","objectifs":[{"id":"353-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du suicide, du suicidé, du suicidant, du suicidaire","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">conduites suicidaires</span></strong> regroupent les <span class=\"kw-def\">suicides</span> et les <span class=\"kw-def\">tentatives de suicide</span>. Quatre statuts terminologiques sont à distinguer avec précision — un grand classique de QCM.</p>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Suicide</strong></td>\n            <td>Acte délibéré de <span class=\"kw-def\">mettre fin à sa propre vie</span> = suicide « <span class=\"kw-def\">abouti</span> ».</td>\n          </tr>\n          <tr>\n            <td><strong>Tentative de suicide (TS)</strong></td>\n            <td>Comportement auto-infligé <strong>avec <span class=\"kw-def\">intention de mourir</span></strong>, sans issue fatale = suicide <span class=\"kw-def\">inabouti</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Équivalents suicidaires</strong></td>\n            <td>Conduites à risque mettant la vie en jeu <strong>sans expression d'un désir ou d'une volonté de mort</strong> : <span class=\"kw-clinique\">automutilations</span> ; prises de risque ; <span class=\"kw-clinique\">mauvaise observance</span> ou <span class=\"kw-clinique\">refus de soins</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Idées suicidaires</strong></td>\n            <td>Pensées concernant le <span class=\"kw-def\">désir et la méthode de se donner la mort</span> — des <span class=\"kw-clinique\">idées morbides vagues et floues</span> jusqu'à une <span class=\"kw-alerte\">planification élevée avec scénario établi</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Personne suicidée</strong></td>\n            <td>Personne qui s'est donné la mort volontairement.</td>\n          </tr>\n          <tr>\n            <td><strong>Personne suicidante</strong></td>\n            <td>Individu <span class=\"kw-def\">survivant à sa TS</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Personne suicidaire</strong></td>\n            <td>Individu ayant ou exprimant — verbalement ou non — des <span class=\"kw-clinique\">idées suicidaires</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> On parle de suicide « <span class=\"kw-def\">abouti</span> », <span class=\"kw-ci\">jamais de</span> suicide « réussi ». Et la <span class=\"kw-clinique\">TS</span> se distingue de l'<span class=\"kw-def\">équivalent suicidaire</span> par la présence d'une <strong>intention de mourir</strong> — une conduite ordalique ou une automutilation n'en comporte pas.\n      </div>","frequence":0},{"id":"353-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","contenu":"<p>Trois ordres de grandeur structurent l'<span class=\"kw-def\">épidémiologie</span> : le <span class=\"kw-def\">suicide</span> (issue fatale), la <span class=\"kw-clinique\">tentative de suicide</span> (issue non fatale) et <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">idées suicidaires</span>.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Chiffres clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Suicide</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Incidence</span> :</strong> <span class=\"kw-chiffre\">~9 000/an</span> en France = <span class=\"kw-chiffre\">6/100 000/an</span> (<span class=\"kw-chiffre\">25</span> chez l'homme, <span class=\"kw-chiffre\">8,0</span> chez la femme) ; <span class=\"kw-chiffre\">1 suicide / 40 min</span><br>\n              <strong><span class=\"kw-def\">Mortalité</span> :</strong> <span class=\"kw-alerte\">1ʳᵉ cause de mortalité</span> chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">25-35 ans</span> ; <span class=\"kw-alerte\">2ᵉ cause</span> chez les <span class=\"kw-chiffre\">15-25 ans</span><br>\n              <strong>Âge :</strong> le taux <strong>augmente avec l'âge</strong> — rare chez l'adolescent, fréquent chez l'homme âgé<br>\n              <strong>Sexe :</strong> surmortalité masculine nette = <span class=\"kw-chiffre\">3 H / 1 F</span><br>\n              <strong>Modes :</strong> pendaison &gt; armes à feu (homme) &gt; médicaments &gt; saut dans le vide\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tentative de suicide</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Incidence</span> :</strong> <span class=\"kw-chiffre\">150 000-200 000 TS/an</span> avec <span class=\"kw-def\">contact</span> du système de soins = <span class=\"kw-chiffre\">1 TS / 4 min</span><br>\n              <strong><span class=\"kw-def\">Prévalence</span> :</strong> <span class=\"kw-chiffre\">7,2 %</span> des adultes ont fait une TS au cours de leur vie ; <span class=\"kw-chiffre\">0,4 %</span> sur <span class=\"kw-clinique\">les</span> 12 derniers mois<br>\n              <strong>Récidive :</strong> <span class=\"kw-alerte\">40 %</span> après une TS, dont la moitié survient dans l'année<br>\n              <strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">mortalité</span> par suicide l'année suivant une TS = <span class=\"kw-alerte\">1 %</span> (50× la population générale) ; <span class=\"kw-chiffre\">10 %</span> de décès par suicide au cours de la vie chez les sujets ayant fait une TS<br>\n              <strong>Sexe :</strong> prédominance <strong>féminine</strong> des TS (mais TS moins mortelles)<br>\n              <strong>Moyens :</strong> IMV ; phlébotomie ; saut d'une grande hauteur ; pendaison\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Idées suicidaires</strong></td>\n            <td>\n              <strong>Adultes (<span class=\"kw-chiffre\">18-85 ans</span>) :</strong> <span class=\"kw-chiffre\">4,2 %</span> y ont pensé sur <span class=\"kw-clinique\">les</span> 12 derniers mois<br>\n              <strong>Adolescents :</strong> <span class=\"kw-chiffre\">5-10 %</span> sur les 12 derniers mois, avec prédominance féminine (<span class=\"kw-chiffre\">2 F / 1 G</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span> pronostique.</strong> Une <span class=\"kw-clinique\">tentative de suicide</span> multiplie par <span class=\"kw-alerte\">50</span> le risque de décès par suicide dans l'année — soit <span class=\"kw-alerte\">1 %</span> de <span class=\"kw-def\">mortalité</span> à<span class=\"kw-chiffre\"> 1 an</span>. Tout suicidant relève d'un <span class=\"kw-def\">suivi</span> rapproché, jamais d'un simple retour à domicile.\n      </div>","frequence":3},{"id":"353-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une crise suicidaire","contenu":"<p>La <strong><span class=\"kw-def\">crise suicidaire</span></strong> est une <span class=\"kw-def\">crise psychique</span> survenant dans un contexte de vulnérabilité, marquée par l'<strong>émergence et l'expression d'idées suicidaires</strong>. C'est un état <span class=\"kw-def\">réversible et temporaire</span> — avec un début et une fin — dont le <span class=\"kw-alerte\">risque majeur est le suicide</span>.</p>\n      <p><strong>Mécanisme.</strong> La crise survient lorsque <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">ressources adaptatives sont épuisées</span>. Le processus est progressif :</p>\n      <ol>\n        <li><strong>Phase initiale</strong> — la personne en <span class=\"kw-alerte\">détresse</span> <span class=\"kw-clinique\">explore des alternatives</span> (soutien social, soins, changement de situation).</li>\n        <li><strong>Échec progressif</strong> — chaque solution qui échoue (perte d'un espoir, absence de soutien, aggravation des symptômes) réduit <span class=\"kw-clinique\">les</span> options perçues.</li>\n        <li><strong>Accumulation des échecs</strong> — le <span class=\"kw-alerte\">sentiment d'impasse</span> se renforce, <span class=\"kw-clinique\">les</span> idées suicidaires deviennent centrales.</li>\n        <li><strong>Phase critique</strong> — si toutes <span class=\"kw-clinique\">les</span> alternatives perçues échouent, le <span class=\"kw-alerte\">suicide apparaît comme la seule issue</span>.</li>\n      </ol>\n      <p><strong>Manifestations cliniques</strong> — souvent peu spécifiques :</p>\n      <ul>\n        <li>Symptômes <span class=\"kw-clinique\">dépressifs ou anxieux</span> non spécifiques.</li>\n        <li><span class=\"kw-clinique\">Isolement</span>, retrait des marques d'affection et du <span class=\"kw-def\">contact</span> physique.</li>\n        <li><span class=\"kw-clinique\">Prises de risque inconsidérées</span>, consommation de substances psychoactives.</li>\n      </ul>\n      <p><strong>Idées et comportements préoccupants :</strong> sentiment de <span class=\"kw-alerte\">désespoir</span> ; souffrance psychique intense ; <span class=\"kw-ttt\">réduction</span> du sens des valeurs, cynisme ; goût pour le morbide ; <span class=\"kw-alerte\">recherche soudaine de moyens létaux</span>.</p>\n      <p><strong>Questionner sans crainte.</strong> Il ne faut <strong>jamais hésiter à interroger directement</strong> le patient sur l'existence d'idées de suicide : cela ne <span class=\"kw-clinique\">les</span> fait pas émerger et <span class=\"kw-def\">favorise leur expression</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Syndrome présuicidaire de Ringel.</strong> Signes faisant évoquer un risque imminent de passage à l'acte : comportements <span class=\"kw-alerte\">préparatoires</span> (rédaction de lettres, dispositions testamentaires, dons) et surtout l'<strong><span class=\"kw-alerte\">ACCALMIE</span></strong> — calme apparent, attitude de retrait, effondrement de la réactivité émotionnelle et affective, de l'agressivité et des échanges interpersonnels. Cette accalmie est trompeuse : elle <strong>précède le passage à l'acte</strong>, elle ne signe pas une amélioration.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 63 — Trouble schizophrénique</em></p>","frequence":3},{"id":"353-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les formes cliniques selon l’âge","contenu":"<p>La présentation clinique de la crise suicidaire varie fortement avec l'âge. La <span class=\"kw-def\">prise en charge spécifique</span> de l'enfant-adolescent et du sujet âgé est détaillée dans <span class=\"kw-clinique\">les</span> objectifs dédiés de la rubrique Prise en charge.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Présentation clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td>\n              <strong>Âge :</strong> idées et intentions suicidaires possibles dès <span class=\"kw-chiffre\">5-6 ans</span> (expression dépendante du niveau développemental)<br>\n              <strong>Signes aspécifiques :</strong> <span class=\"kw-clinique\">irritabilité</span> ; <span class=\"kw-clinique\">agitation</span> ; repli, <span class=\"kw-def\">isolement</span> ; baisse des résultats scolaires ; <span class=\"kw-clinique\">régression développementale</span> (encoprésie, énurésie secondaires) ; <span class=\"kw-clinique\">plaintes physiques</span> (douleurs, <span class=\"kw-clinique\">céphalées</span>, maux de ventre)<br>\n              <strong>Signes spécifiques :</strong> préoccupations exagérées pour la mort ; blessures à répétition ou comportements de mise en danger à dimension suicidaire<br>\n              <strong>Moyens :</strong> pendaison/strangulation ; défenestration\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Adolescent</strong></td>\n            <td>\n              <strong>Manifestations :</strong> baisse des résultats scolaires ; attirance pour la marginalité ; <span class=\"kw-clinique\">fugues</span> ; conduites d'<span class=\"kw-clinique\">anorexie</span> ou de <span class=\"kw-clinique\">boulimie</span> ; conduites addictives ; prises de risque (notamment sexuel) ; <span class=\"kw-alerte\">conduites ordaliques</span> (le sujet remet sa survie aux mains du hasard)<br>\n              <strong>Moyen :</strong> <span class=\"kw-alerte\">intoxication médicamenteuse dans 80 % des cas</span> (psychotropes surtout)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td>Idées suicidaires <span class=\"kw-clinique\">peu exprimées ou manifestes</span>. Manifestations : ennui, sentiment de perte de rôle, d'échec, d'injustice ; <span class=\"kw-clinique\">arrêts de travail à répétition</span> ou au contraire surinvestissement professionnel ; consultations répétées pour symptômes aspécifiques ; difficultés relationnelles et conjugales.</td>\n          </tr>\n          <tr>\n            <td><strong>Sujet âgé</strong></td>\n            <td>Idées suicidaires <strong>rarement exprimées</strong> (ou peu d'occasions de l'être) — <span class=\"kw-alerte\">à ne jamais banaliser</span>. Manifestations : <span class=\"kw-clinique\">repli sur soi</span> ; perte d'intérêt pour <span class=\"kw-clinique\">les</span> activités ; <span class=\"kw-clinique\">refus de s'alimenter</span> ; refus de soin.</td>\n          </tr>\n          <tr>\n            <td><strong>Patient avec trouble psychiatrique</strong></td>\n            <td><span class=\"kw-alerte\">FR majeur de suicide</span> — risque à évaluer en permanence. Signes d'augmentation du risque : <span class=\"kw-clinique\">isolement avec rupture des contacts habituels</span> ; abandon des activités habituelles ; <span class=\"kw-alerte\">exacerbation des symptômes psychiatriques</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Chez l'<span class=\"kw-def\">enfant</span> comme chez le <span class=\"kw-def\">sujet âgé</span>, l'expression d'idées suicidaires ne doit <strong>jamais être banalisée</strong> : elle constitue un motif d'intervention. Tout enfant exprimant des idées suicidaires n'est pas pour autant en crise (ex. <span class=\"kw-alerte\">menace</span> sous l'emprise de la colère), mais tout propos suicidaire impose une évaluation attentive.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 68 — Troubles du comportement de l'ado · 70 — Troubles psychiques du sujet agê</em></p>","frequence":0},{"id":"353-5","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évaluer le risque, l’urgence et la dangerosité (RUD) à tous les âges de la vie","contenu":"<p>L'évaluation de la crise suicidaire repose sur <strong>3 axes</strong> — l'échelle <strong><span class=\"kw-def\">RUD</span></strong> : <strong>R</strong>isque, <strong>U</strong>rgence, <strong>D</strong>angerosité. Elle s'applique <strong>à tous <span class=\"kw-clinique\">les</span> âges de la vie</strong>.</p>\n\n      <p><strong>1 · Risque</strong> — recherche des <span class=\"kw-etio\">facteurs de risque</span> et des <span class=\"kw-def\">facteurs protecteurs</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sexe</strong></td>\n            <td>Le <span class=\"kw-etio\">sexe masculin</span> augmente le risque de <strong>décès</strong> par suicide.</td>\n          </tr>\n          <tr>\n            <td><strong>Personnels</strong></td>\n            <td>Expression d'idées suicidaires ; <span class=\"kw-etio\">ATCD personnels de TS</span> ; pathologie altérant la qualité de vie ; <span class=\"kw-etio\">trouble psychiatrique</span> ; consommation de toxiques ; trouble de la personnalité (faible estime de soi, impulsivité-agressivité, rigidité, désespoir, <span class=\"kw-alerte\">blessure narcissique</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Familiaux</strong></td>\n            <td>ATCD familiaux de <span class=\"kw-clinique\">TS</span>, de <span class=\"kw-def\">suicide</span>, de maladie psychiatrique, d'addiction.</td>\n          </tr>\n          <tr>\n            <td><strong>Événements de l'enfance</strong></td>\n            <td>Difficultés scolaires ; perte parentale précoce ; <span class=\"kw-etio\">maltraitance</span> (violences, abus physique, émotionnel ou sexuel) ; placement en foyer ou en détention.</td>\n          </tr>\n          <tr>\n            <td><strong>Psychosociaux</strong></td>\n            <td><span class=\"kw-etio\">Élément déclencheur</span> récent ; difficultés économiques ou professionnelles ; <span class=\"kw-etio\">isolement social</span> ; séparation ou perte récente ; difficultés avec la loi ; échecs ou événements humiliants ; <span class=\"kw-alerte\">contagion</span> après le suicide récent d'un proche ; appartenance LGBT.</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs protecteurs</strong></td>\n            <td><strong>Individuel :</strong> <span class=\"kw-def\">résilience</span> (capacité à fonctionner de manière adaptée face à l'adversité)<br><strong>Psychosocial :</strong> soutien socio-familial perçu ; avoir des enfants ; croyance religieuse</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>2 · <span class=\"kw-alerte\">Urgence</span></strong> — évaluation du <span class=\"kw-def\">projet suicidaire</span>, gradée en trois niveaux.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Urgence faible</th><th>Urgence moyenne</th><th>Urgence élevée</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Isolement</span></strong></td><td>Bonne alliance thérapeutique</td><td>Isolé</td><td><span class=\"kw-alerte\">Très isolé</span></td></tr>\n          <tr><td><strong>Communication</strong></td><td><span class=\"kw-clinique\">Désire parler</span></td><td>Exprime son désarroi, demande de l'aide</td><td>Agitation ou ralentissement majeur ; souffrance omniprésente ou totalement tue</td></tr>\n          <tr><td><strong>Alternatives</strong></td><td>Cherche des solutions</td><td>Ne voit pas d'autre recours</td><td><span class=\"kw-alerte\">Idées envahissantes, ruminations anxieuses, refus des soins</span></td></tr>\n          <tr><td><strong>Scénario</strong></td><td>Pas de scénario précis</td><td>Scénario envisagé mais reporté</td><td><span class=\"kw-alerte\">Accès direct et immédiat à un moyen</span></td></tr>\n          <tr><td><strong>Décision</strong></td><td>Envisage d'autres moyens de surmonter la crise</td><td>Envisage le suicide avec intention claire</td><td><span class=\"kw-alerte\">Décidé, passage à l'acte planifié et prévu dans les jours qui viennent</span></td></tr>\n          <tr><td><strong>État psychologique</strong></td><td>Souffrant mais sans trouble</td><td>Équilibre émotionnel fragile</td><td>Coupé de ses émotions (rationalise) ou très agité/anxieux</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>3 · Dangerosité</strong> — évaluation des <span class=\"kw-def\">moyens à disposition</span> selon leur <strong>létalité potentielle</strong> et leur <strong>accessibilité</strong>. Gradée faible / moyenne / élevée :</p>\n      <ul>\n        <li><strong>Dangerosité faible</strong> — ex. vouloir se suicider par arme à feu <strong>sans en posséder</strong> : l'absence d'accès immédiat laisse une <span class=\"kw-def\">possibilité d'intervention</span>.</li>\n        <li><strong>Dangerosité élevée</strong> — ex. vouloir se suicider par <span class=\"kw-alerte\">IMV avec des connaissances médicales</span> : connaissance des doses létales + accès direct au moyen → passage à l'acte plus probable et plus rapide.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-alerte\">intention suicidaire avec moyens immédiatement disponibles</span> est bien plus urgente qu'une idée suicidaire sans accès au moyen. La <strong>sécurisation immédiate</strong> des moyens létaux (retrait des armes, restriction d'accès aux médicaments, <span class=\"kw-alerte\">hospitalisation</span> si besoin) fait partie intégrante de l'évaluation.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif</em></p>","frequence":9},{"id":"353-6","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales mesures de prévention primaire, secondaire et tertiaire","contenu":"<p>La prévention du suicide se décline classiquement en <strong>trois niveaux</strong>.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Définition et mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Primaire</strong></td>\n            <td>Identifier <span class=\"kw-clinique\">les</span> sujets <strong>non en crise</strong> mais porteurs de <span class=\"kw-etio\">facteurs de risque</span>. Supprimer les FR et facteurs de <span class=\"kw-alerte\">décompensation</span> : traiter un <span class=\"kw-etio\">épisode dépressif caractérisé</span> ; prévenir l'accès aux <span class=\"kw-alerte\">moyens létaux</span> (posologie totale des boîtes de <span class=\"kw-ttt\">paracétamol</span>, sécurisation de la pharmacie du domicile) ; prévenir le passage à l'acte chez les patients hospitalisés en psychiatrie.</td>\n          </tr>\n          <tr>\n            <td><strong>Secondaire</strong></td>\n            <td><span class=\"kw-def\">Dépistage précoce</span> de la crise suicidaire, réalisé par tout personnel soignant, débouchant sur une orientation adaptée.</td>\n          </tr>\n          <tr>\n            <td><strong>Tertiaire</strong></td>\n            <td>Prise en charge des <span class=\"kw-def\">personnes suicidantes</span> pour éviter la <span class=\"kw-alerte\">récidive</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Acteurs :</strong> réseaux d'accueil et d'écoute (pouvant intervenir à tout niveau), <span class=\"kw-clinique\">médecine scolaire</span> et <span class=\"kw-clinique\">médecine du travail</span>.</p>\n      <p><strong>Guide HEADSSSS</strong> — outil structuré d'entretien psychosocial de l'adolescent (<span class=\"kw-def\">prévention primaire</span>), permettant de repérer <span class=\"kw-clinique\">les</span> vulnérabilités de façon globale et non intrusive :</p>\n      <table >\n        <thead><tr><th>Lettre</th><th>Domaine</th><th>Éléments évalués</th></tr></thead>\n        <tbody>\n          <tr><td><strong>H</strong></td><td>Habitation (Home)</td><td>Relations familiales, environnement domestique</td></tr>\n          <tr><td><strong>E</strong></td><td>École (Education/Employment)</td><td>Difficultés scolaires, absences, stress, ambitions</td></tr>\n          <tr><td><strong>A</strong></td><td>Alimentation</td><td><span class=\"kw-clinique\">Troubles du comportement alimentaire</span></td></tr>\n          <tr><td><strong>A</strong></td><td>Activités</td><td>Loisirs, amis, usage d'internet</td></tr>\n          <tr><td><strong>D</strong></td><td>Drogues</td><td><span class=\"kw-etio\">Tabac</span>, <span class=\"kw-etio\">alcool</span>, drogues, substances toxiques</td></tr>\n          <tr><td><strong>S</strong></td><td>Sexualité</td><td>Vie affective et sexuelle, <span class=\"kw-clinique\">IST</span>, contraception, <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><strong>S</strong></td><td>Suicide</td><td><span class=\"kw-clinique\">Idées suicidaires</span>, ATCD de TS, <span class=\"kw-etio\">dépression</span></td></tr>\n          <tr><td><strong>S</strong></td><td>Sévices subis (Safety)</td><td>Violences physiques, psychologiques, sexuelles, harcèlement</td></tr>\n          <tr><td><strong>S</strong></td><td>Symptômes flous (somatiques)</td><td>Douleurs inexpliquées, <span class=\"kw-clinique\">céphalées</span>, troubles du sommeil</td></tr>\n        </tbody>\n      </table>\n      <p><strong>6 mesures efficaces de l'OMS :</strong></p>\n      <ul>\n        <li>Restreindre l'accès aux <span class=\"kw-alerte\">moyens létaux</span>.</li>\n        <li>Responsabiliser <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">médias</span>.</li>\n        <li>Adopter des politiques sur l'<span class=\"kw-etio\">alcool</span>.</li>\n        <li>Identifier précocement et traiter.</li>\n        <li>Former <span class=\"kw-clinique\">les</span> agents de santé.</li>\n        <li>Assurer des soins de <span class=\"kw-def\">suivi</span> et de soutien dans la communauté.</li>\n      </ul>\n      <p><strong>5 piliers de la stratégie nationale :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">3114</span></strong> — numéro national de prévention du suicide, accessible <span class=\"kw-chiffre\">24h</span>/24 et <span class=\"kw-chiffre\">7j</span>/7 (accueil, évaluation, intervention, orientation).</li>\n        <li><strong><span class=\"kw-def\">VigilanS</span></strong> — dispositif de prévention de la réitération suicidaire : veille active et recontacts (appels, cartes postales) après une TS.</li>\n        <li>Prévention de la <span class=\"kw-alerte\">contagion suicidaire</span> — meilleur traitement médiatique, postvention dans <span class=\"kw-clinique\">les</span> institutions, prévention des <em>hotspots</em>.</li>\n        <li>Formation des acteurs de la prévention et déploiement de <span class=\"kw-def\">sentinelles</span>.</li>\n        <li>Communication grand public.</li>\n      </ul>\n      <p><strong>Spécificités adolescent :</strong> <span class=\"kw-def\">prévention primaire</span> via le guide <span class=\"kw-def\">HEADSSSS</span> ; <span class=\"kw-def\">prévention tertiaire</span> par la remise d'une carte avec <span class=\"kw-clinique\">les</span> coordonnées du médecin et le numéro de <span class=\"kw-def\">Fil Santé Jeunes</span> ; acteurs = réseaux locaux, Maisons des adolescents, services de santé mentale.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 60 — FdR, prévention, <span class=\"kw-def\">dépistage</span> des troubles psychiques</em></p>","frequence":0},{"id":"353-7","rang":"B","rubrique":"Prise en charge","titre":"Aborder le patient suicidaire, connaître les principes de l’entretien","contenu":"<p>L'abord du patient suicidaire repose sur un <span class=\"kw-def\">entretien</span> dont la priorité est d'<strong>évaluer le risque suicidaire</strong>.</p>\n      <p><strong>Règles de l'entretien :</strong></p>\n      <ul>\n        <li>Se dérouler dans un <span class=\"kw-def\">endroit calme</span>, en toute <span class=\"kw-def\">confidentialité</span> et en <strong>face-à-face</strong>.</li>\n        <li>Aborder <span class=\"kw-clinique\">les</span> idées suicidaires <strong>directement</strong> (ex. « avez-vous des idées de suicide ? »).</li>\n      </ul>\n      <p><strong>À ne pas faire :</strong> ne pas dramatiser la situation, laisser le patient s'exprimer ; mais ne <strong>jamais banaliser</strong> <span class=\"kw-clinique\">les</span> conduites suicidaires — elles constituent une <span class=\"kw-alerte\">urgence psychiatrique</span>.</p>\n      <p><strong>Rôle de l'entourage :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Contact</span> avec la famille/l'entourage pour repérer <span class=\"kw-clinique\">les</span> soutiens possibles, dans le <span class=\"kw-def\">respect du secret médical</span>.</li>\n        <li>Instaurer une <span class=\"kw-def\">relation de confiance</span> : bienveillance, écoute, dialogue.</li>\n        <li>Deux réactions familiales favorables : reconnaître la <strong>gravité de l'acte</strong> (<span class=\"kw-bio\">vs</span> banalisation) et reconnaître la <strong>souffrance psychique</strong> de chacun (<span class=\"kw-bio\">vs</span> déni).</li>\n      </ul>\n      <p><strong>Au long cours :</strong> un <span class=\"kw-def\">suivi</span> est nécessaire <strong>même en cas d'amélioration symptomatique</strong>. Un <strong><span class=\"kw-def\">plan de sécurité</span></strong> personnalisé est élaboré avec le patient — liste de ressources mobilisables avant et pendant une crise : personnes-ressources, numéro de téléphone d'<span class=\"kw-alerte\">urgence</span>, activités apaisantes, techniques de réassurance.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> L'<span class=\"kw-clinique\">amélioration symptomatique</span> est fréquente dans <span class=\"kw-clinique\">les</span> jours qui suivent un passage à l'acte — elle ne signe <strong>pas</strong> la fin du risque. Le <span class=\"kw-def\">suivi au long cours</span> reste indispensable.\n      </div>","frequence":2},{"id":"353-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir en urgence","contenu":"<p>Devant un patient suicidaire ou suicidant, la conduite à tenir hiérarchise <strong>somatique puis psychiatrique</strong>.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> — ordre de prise en charge.</strong> L'avis psychiatrique est sollicité pour tout patient suicidaire ou suicidant <strong>après stabilisation de l'état clinique non psychiatrique</strong> : le <span class=\"kw-alerte\">somatique est traité AVANT</span> le transfert en psychiatrie.\n      </div>\n      <p><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> (en soins libres ou en soins sans consentement) — objectifs :</p>\n      <ul>\n        <li><strong>Protéger le patient</strong> en limitant le risque de passage à l'acte : <span class=\"kw-def\">limiter l'accès aux moyens létaux</span> (inventaire des affaires, retrait des objets dangereux, blocage des fenêtres) ; <span class=\"kw-def\">surveillance rapprochée</span> (chambre à proximité de l'infirmerie, voire <span class=\"kw-def\">surveillance</span> à vue en permanence).</li>\n        <li><span class=\"kw-def\">Psychothérapie de soutien</span> pour faciliter la résolution de la crise.</li>\n      </ul>\n      <p><strong>Traitement <span class=\"kw-etio\">médicamenteux</span> symptomatique :</strong></p>\n      <table >\n        <thead><tr><th>Symptôme cible</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Agitation / anxiété importante</strong></td><td><span class=\"kw-ttt\">Anxiolytique</span> ou <span class=\"kw-ttt\">sédatif</span></td></tr>\n          <tr><td><strong>Insomnie sévère transitoire</strong></td><td><span class=\"kw-ttt\">Hypnotique</span></td></tr>\n          <tr><td><strong>Impulsivité importante</strong></td><td><span class=\"kw-ci\">Éviter une 1ʳᵉ prise de BZD</span> ; privilégier un antipsychotique sédatif de type phénothiazine (ex. <span class=\"kw-ttt\">cyamémazine</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span> thérapeutique.</strong> Devant une <span class=\"kw-alerte\">impulsivité importante</span>, <span class=\"kw-ci\">éviter une première prescription de benzodiazépine</span> (effet désinhibiteur possible) — privilégier une <span class=\"kw-ttt\">phénothiazine</span> sédative (cyamémazine). À retenir aussi : l'<span class=\"kw-alerte\">hospitalisation</span> ne prévient pas tous <span class=\"kw-clinique\">les</span> suicides — environ <span class=\"kw-alerte\">5 %</span> surviennent en établissement de soins (causes principales : défenestration/précipitation et pendaison).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 351 — Agitation et délire aigu · 15 — Soins psychiatriques sans consentement</em></p>","frequence":1},{"id":"353-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications d’hospitalisations","contenu":"<p>L'<span class=\"kw-alerte\">hospitalisation</span> se fait en <span class=\"kw-def\">soins libres</span> ou en <span class=\"kw-def\">soins sans consentement</span>, selon le consentement et l'état du patient.</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Indications d'hospitalisation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications générales</strong></td>\n            <td>Degré d'<span class=\"kw-alerte\">urgence</span> <span class=\"kw-alerte\">élevé</span> ; OU degré d'urgence faible/moyen <strong>associé à des troubles psychiatriques décompensés</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Indications formelles chez l'enfant et l'adolescent</strong></td>\n            <td>Toute <span class=\"kw-clinique\">tentative de suicide</span> ; crise suicidaire avec <span class=\"kw-alerte\">urgence et/ou dangerosité élevée</span> (évaluées par le RUD) ; <span class=\"kw-alerte\">impossibilité de prise en charge à domicile</span> (non-implication des parents, pas d'accès aux soins).</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Chez le mineur, toute <span class=\"kw-clinique\">TS</span> est une indication <strong>formelle</strong> d'<span class=\"kw-alerte\">hospitalisation</span>, indépendamment du niveau de risque résiduel évalué.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement</em></p>","frequence":0},{"id":"353-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les spécificités chez l’enfant et l’adolescent","contenu":"<p>Chez le mineur, la prise en charge est <strong>graduée selon le niveau de risque suicidaire</strong>. La présentation clinique selon l'âge est détaillée dans l'objectif « formes cliniques selon l'âge ».</p>\n      <p><strong>Facteurs de vulnérabilité spécifiques :</strong></p>\n      <ul>\n        <li><strong>Enfant :</strong> <span class=\"kw-etio\">ATCD personnels de TS</span>, maladie chronique, handicap ; troubles psychiatriques (<span class=\"kw-etio\">dépression</span>, TDAH, TSA) ; <span class=\"kw-def\">isolement</span> affectif, <span class=\"kw-etio\">dysrégulation émotionnelle</span> ; ATCD familiaux de TS, <span class=\"kw-etio\">harcèlement</span>, maltraitance, négligence, conflits familiaux, placement à l'ASE.</li>\n        <li><strong>Adolescent :</strong> troubles psychiatriques ; <span class=\"kw-etio\">échecs scolaires</span> et <span class=\"kw-etio\">déscolarisation</span> ; <span class=\"kw-etio\">ruptures sentimentales</span> ; conflits d'autorité, <span class=\"kw-def\">isolement</span> affectif.</li>\n        <li><strong>Facteur protecteur majeur :</strong> le <span class=\"kw-def\">soutien familial</span>.</li>\n      </ul>\n      <p><strong>Prise en charge selon le risque suicidaire :</strong></p>\n      <table >\n        <thead><tr><th>Risque</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Faible</strong></td>\n            <td>Pas d'<span class=\"kw-alerte\">hospitalisation</span> en l'absence d'autre motif. Vérifier que l'adolescent a des <span class=\"kw-def\">adultes de confiance</span> dans son entourage ; transmettre le numéro de <span class=\"kw-def\">Fil Santé Jeunes</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Moyen</strong></td>\n            <td>Consultation d'évaluation rapide à programmer (<span class=\"kw-def\">CMP</span>, <span class=\"kw-def\">CMPP</span>, psychiatre libéral, consultation post-<span class=\"kw-alerte\">urgence</span>). Informer <span class=\"kw-clinique\">les</span> parents des idées suicidaires ; mettre hors de portée les <span class=\"kw-alerte\">moyens létaux</span> du domicile (psychotropes, <span class=\"kw-ttt\">paracétamol</span>, armes à feu).</td>\n          </tr>\n          <tr>\n            <td><strong>Élevé</strong></td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> nécessaire (au minimum en <span class=\"kw-def\">UHCD</span>). Évaluation par un médecin d'adolescent et/ou un psychiatre ; transfert en <span class=\"kw-def\">pédopsychiatrie</span> envisagé.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Le moyen de TS prédominant à l'adolescence est l'<span class=\"kw-alerte\">intoxication médicamenteuse (80 % des cas)</span> — d'où l'importance de sécuriser la pharmacie du domicile dès le risque moyen.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 68 — Troubles du comportement de l'ado</em></p>","frequence":4},{"id":"353-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les spécificités chez le sujet âgé","contenu":"<p>Le sujet âgé constitue une population <span class=\"kw-alerte\">à haut risque</span>, dont <span class=\"kw-clinique\">les</span> conduites suicidaires ont des particularités propres. La France est l'un des pays européens où le taux de suicide de la personne âgée est le plus élevé.</p>\n      <table >\n        <thead><tr><th>Dimension</th><th>Données</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Épidémiologie</span></strong></td>\n            <td><span class=\"kw-chiffre\">30 %</span> des suicides surviennent chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">≥ 65 ans</span> ; <span class=\"kw-def\">prévalence</span> du suicide <span class=\"kw-chiffre\">1/1 000</span> chez les <span class=\"kw-chiffre\">≥ 85 ans</span> ; prédominance masculine (<span class=\"kw-chiffre\">54 %</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs de vulnérabilité</strong></td>\n            <td><span class=\"kw-etio\">Épisode dépressif caractérisé</span> quasiment constant (<span class=\"kw-chiffre\">90 %</span> des cas) ; autres troubles psychiatriques (<span class=\"kw-etio\">alcoolisme</span>, personnalité psychorigide) ; affection médicale handicapante ou douloureuse ; <span class=\"kw-etio\">isolement social</span>, conflits, maltraitance, changement d'environnement, <span class=\"kw-etio\">veuvage</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs protecteurs</strong></td>\n            <td>Activités de loisirs ou associatives ; vie sociale riche ; sentiment d'être utile.</td>\n          </tr>\n          <tr>\n            <td><strong>Particularités des conduites suicidaires</strong></td>\n            <td>Intentionnalité suicidaire élevée — <span class=\"kw-alerte\">réussite des suicides 50× supérieure</span> à celle d'un sujet jeune ; faible niveau d'impulsivité et d'agressivité ; peu d'ATCD personnels de conduite suicidaire ; moyens souvent radicaux.</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>Recherche systématique de <span class=\"kw-etio\">troubles psychiatriques comorbides</span> (notamment un EDC) ; tout changement comportemental récent fait envisager une <span class=\"kw-alerte\">douleur physique</span> et/ou une <span class=\"kw-etio\">maltraitance</span> ; évaluation psychosociale systématique.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> En cas de crise suicidaire avérée chez le sujet âgé, il est impératif de <strong>rechercher et retirer du domicile <span class=\"kw-clinique\">les</span> moyens de mort violente</strong>. L'intentionnalité est élevée et les moyens radicaux : la réussite des suicides est <span class=\"kw-alerte\">50× supérieure</span> à celle d'un sujet jeune. Les idées suicidaires, rarement exprimées, ne doivent jamais être banalisées.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 70 — Troubles psychiques du sujet agê · 66 — Trouble dépressif</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> toute conduite suicidaire est une <span class=\"kw-alerte\">urgence psychiatrique</span> — <span class=\"kw-ci\">ne jamais</span> <span class=\"kw-alerte\">banaliser</span> <span class=\"kw-clinique\">les</span> idées ni les propos suicidaires.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">traiter le somatique AVANT</span> tout transfert en psychiatrie, puis évaluer la crise par l'échelle <span class=\"kw-def\">RUD</span> (Risque · Urgence · Danger).<br><strong>Sécurisation immédiate :</strong> <span class=\"kw-ttt\">limiter l'accès aux moyens létaux</span> dès l'évaluation (retrait des armes, restriction d'accès aux médicaments).<br><strong>Avis spécialisé :</strong> avis psychiatrique pour tout patient suicidaire ou suicidant, après <span class=\"kw-clinique\">stabilisation de l'état clinique non psychiatrique</span>.<br><strong>Questionner :</strong> interroger directement sur les idées de suicide ne les fait pas émerger et <span class=\"kw-def\">favorise leur expression</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">risque faible</span> sans autre motif — s'assurer d'un entourage de confiance et transmettre <span class=\"kw-clinique\">les</span> ressources (<span class=\"kw-def\">3114</span>, <span class=\"kw-def\">Fil Santé Jeunes</span> chez l'ado).<br><strong>Consultation rapide :</strong> <span class=\"kw-clinique\">risque moyen</span> — orientation vers <span class=\"kw-ttt\">CMP</span>, <span class=\"kw-ttt\">CMPP</span>, psychiatre libéral ou consultation post-<span class=\"kw-alerte\">urgence</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> degré d'<span class=\"kw-alerte\">urgence élevé</span>, OU urgence faible/moyenne associée à un <span class=\"kw-alerte\">trouble psychiatrique décompensé</span> — en <span class=\"kw-ttt\">soins libres</span> ou en <span class=\"kw-ttt\">soins sans consentement</span>.<br><strong>Indications formelles chez le mineur :</strong> toute <span class=\"kw-alerte\">tentative de suicide</span>, urgence et/ou dangerosité élevée, ou <span class=\"kw-alerte\">impossibilité de prise en charge à domicile</span> — au minimum en <span class=\"kw-ttt\">UHCD</span>, puis transfert en pédopsychiatrie.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Syndrome présuicidaire de Ringel</span> : l'« <span class=\"kw-alerte\">ACCALMIE</span> » trompeuse — calme apparent, attitude de retrait, effondrement de la réactivité émotionnelle et des échanges ; elle <strong>précède le passage à l'acte</strong> et ne signe pas une amélioration.</li><li><span class=\"kw-alerte\">Comportements préparatoires</span> : rédaction de lettres, dispositions testamentaires, dons, anticipation de la découverte du corps.</li><li><span class=\"kw-alerte\">Accès direct et immédiat à un moyen létal</span> (dangerosité élevée), a fortiori avec des <span class=\"kw-clinique\">connaissances médicales</span> sur <span class=\"kw-clinique\">les</span> doses létales (ex. IMV).</li><li>Sujet <span class=\"kw-alerte\">décidé</span>, scénario planifié et prévu <span class=\"kw-chiffre\">dans les jours qui viennent</span> (préméditation, lettre, testament).</li><li><span class=\"kw-alerte\">Idées envahissantes</span>, ruminations anxieuses, <span class=\"kw-alerte\">refus des soins</span>, sentiment d'avoir tout fait et tout essayé.</li><li><span class=\"kw-clinique\">Recherche soudaine de moyens létaux</span> (ex. armes à feu) ; sujet <span class=\"kw-alerte\">très isolé</span>.</li><li><span class=\"kw-clinique\">Tentative de suicide récente</span> : récidive <span class=\"kw-chiffre\">40 %</span>, <span class=\"kw-def\">mortalité</span> par suicide <span class=\"kw-alerte\">1 %</span> à<span class=\"kw-chiffre\"> 1 an</span> (50× la population générale).</li><li>Terrains à risque : <span class=\"kw-alerte\">sujet âgé</span> (réussite des suicides <span class=\"kw-chiffre\">50×</span> supérieure, moyens radicaux) ; <span class=\"kw-etio\">trouble psychiatrique décompensé</span> ; intoxication médicamenteuse (<span class=\"kw-chiffre\">80 %</span> des TS de l'adolescent).</li></ul>","principes":"<p>La prise en charge associe protection immédiate, traitement symptomatique et alliance — l'orientation étant guidée par le <span class=\"kw-def\">RUD</span>.</p><p><strong>Protéger le patient (<span class=\"kw-alerte\">hospitalisation</span>)</strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> en soins libres ou en soins sans consentement selon le consentement et l'<span class=\"kw-alerte\">urgence</span>.</p><ul><li><span class=\"kw-ttt\">Limiter l'accès aux moyens létaux</span> : inventaire des affaires, retrait des objets dangereux, <span class=\"kw-ttt\">blocage des fenêtres</span>.</li><li><span class=\"kw-ttt\">Surveillance rapprochée</span> : passages réguliers, chambre à proximité de l'infirmerie, voire <span class=\"kw-ttt\">surveillance à vue</span> en permanence.</li><li><span class=\"kw-ttt\">Psychothérapie de soutien</span> pour faciliter la résolution de la crise.</li></ul><p><strong>Traitement <span class=\"kw-etio\">médicamenteux</span> symptomatique</strong></p><p>Traiter le trouble psychiatrique sous-jacent (ex. épisode dépressif caractérisé).</p><ul><li>Agitation ou anxiété importante : <span class=\"kw-ttt\">anxiolytique</span> ou <span class=\"kw-ttt\">sédatif</span>.</li><li>Insomnie sévère transitoire : <span class=\"kw-ttt\">hypnotique</span>.</li><li>Impulsivité importante : <span class=\"kw-ci\">éviter une 1ʳᵉ prise de BZD</span>, privilégier un antipsychotique sédatif de type phénothiazine (ex. <span class=\"kw-ttt\">cyamémazine</span>).</li></ul><p><strong>Entretien & alliance thérapeutique</strong></p><ul><li>Entretien dans un <span class=\"kw-ttt\">endroit calme</span>, en confidentialité et en face-à-face ; aborder <span class=\"kw-clinique\">les</span> idées suicidaires <span class=\"kw-ttt\">directement</span>.</li><li>Ne pas dramatiser mais <span class=\"kw-alerte\">ne jamais banaliser</span> ; <span class=\"kw-def\">contact</span> avec l'entourage dans le respect du <span class=\"kw-def\">secret médical</span>.</li><li>Élaborer un <span class=\"kw-ttt\">plan de sécurité</span> personnalisé : personnes-ressources, numéro d'<span class=\"kw-alerte\">urgence</span>, activités apaisantes, techniques de réassurance.</li></ul>","suivi":"<p><strong>Rythme :</strong> <span class=\"kw-ttt\">suivi au long cours</span> indispensable, <span class=\"kw-alerte\">même en cas d'amélioration symptomatique</span> (fréquente et trompeuse dans <span class=\"kw-clinique\">les</span> jours suivant le passage à l'acte).<br><strong>Réitération :</strong> dispositif <span class=\"kw-ttt\">VigilanS</span> après une TS — veille active et recontacts (appels, cartes postales) pour prévenir la <span class=\"kw-alerte\">récidive</span> (<span class=\"kw-chiffre\">40 %</span>, dont la moitié dans l'année).<br><strong><span class=\"kw-def\">Surveillance</span> hospitalière :</strong> passages réguliers, <span class=\"kw-ttt\">surveillance rapprochée voire à vue</span>, maintien de la sécurisation des moyens létaux.<br><strong>Ressources :</strong> <span class=\"kw-def\">plan de sécurité</span> personnalisé ; numéro <span class=\"kw-def\">3114</span> ; chez l'adolescent, carte avec les coordonnées du médecin et <span class=\"kw-def\">Fil Santé Jeunes</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient suicidaire ou suicidant — Ne jamais banaliser — urgence psychiatrique","detail":"<h4>CAT — Crise suicidaire (évaluation RUD) — De l'évaluation du risque à l'orientation</h4>","branches":[{"to":"t-somatique","label":"Geste réalisé / atteinte somatique","color":"red"},{"to":"q-urgence","label":"Patient stable → évaluer RUD","color":"blue"}]},{"id":"t-somatique","kind":"terminal","label":"Stabilisation somatique en priorité — Le somatique est traité AVANT le transfert psychiatrique","color":"red","detail":"<h4>Conduite</h4><ul><li>Traiter l'<span class=\"kw-alerte\">état clinique non psychiatrique</span> avant tout transfert.</li><li>Sécuriser et <span class=\"kw-ttt\">retirer les moyens létaux</span>.</li></ul><h4>Délai</h4><ul><li><span class=\"kw-ttt\">Avis psychiatrique</span> sollicité après stabilisation, puis évaluation <span class=\"kw-def\">RUD</span> complète.</li></ul>"},{"id":"q-urgence","kind":"decision","label":"Degré d'urgence du projet suicidaire ? — Isolement · scénario · accès au moyen · décision (échelle RUD)","branches":[{"to":"t-hospit","label":"Urgence élevée","color":"red"},{"to":"q-decomp","label":"Urgence faible / moyenne","color":"amber"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation (soins libres ou sans consentement) — Urgence élevée, ou urgence faible/moyenne + trouble psy décompensé","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Limiter l'accès aux moyens létaux</span> (retrait des objets dangereux, <span class=\"kw-ttt\">blocage des fenêtres</span>).</li><li><span class=\"kw-ttt\">Surveillance rapprochée</span> voire à vue ; chambre proche de l'infirmerie.</li><li><span class=\"kw-ttt\">Psychothérapie de soutien</span>.</li></ul><h4>Traitement</h4><ul><li>Symptomatique : <span class=\"kw-ttt\">anxiolytique/sédatif</span>, <span class=\"kw-ttt\">hypnotique</span> si insomnie sévère.</li><li>Impulsivité : <span class=\"kw-ci\">éviter une 1ʳᵉ BZD</span>, préférer une phénothiazine (<span class=\"kw-ttt\">cyamémazine</span>).</li></ul><h4>Mineur</h4><ul><li>Toute <span class=\"kw-alerte\">TS</span> = indication formelle — au minimum <span class=\"kw-ttt\">UHCD</span>, puis pédopsychiatrie.</li></ul>"},{"id":"q-decomp","kind":"decision","label":"Trouble psychiatrique décompensé associé ? — Évalue l'urgence faible ou moyenne","branches":[{"to":"t-hospit","label":"Oui","color":"red"},{"to":"t-consult","label":"Non · urgence moyenne","color":"amber"},{"to":"t-ambu","label":"Non · urgence faible","color":"green"}]},{"id":"t-consult","kind":"terminal","label":"Consultation d'évaluation rapide — Urgence moyenne, sans décompensation psychiatrique","color":"amber","detail":"<h4>Conduite</h4><ul><li>Orienter vers <span class=\"kw-ttt\">CMP</span>, <span class=\"kw-ttt\">CMPP</span>, psychiatre libéral ou consultation post-<span class=\"kw-alerte\">urgence</span>.</li><li><span class=\"kw-ttt\">Sécuriser les moyens létaux</span> du domicile (psychotropes, <span class=\"kw-ttt\">paracétamol</span>, armes à feu).</li><li>Informer <span class=\"kw-clinique\">les</span> parents (chez le mineur).</li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Prise en charge ambulatoire — Urgence faible, pas d'autre motif d'hospitalisation","color":"green","detail":"<h4>Conduite</h4><ul><li>S'assurer d'un <span class=\"kw-def\">entourage de confiance</span>.</li><li>Remettre <span class=\"kw-clinique\">les</span> ressources : <span class=\"kw-def\">3114</span>, <span class=\"kw-def\">Fil Santé Jeunes</span> (adolescent).</li><li><span class=\"kw-ttt\">Plan de sécurité</span> et <span class=\"kw-def\">suivi</span> rapproché au long cours.</li></ul>"}]},"cards":[{"i":"1188fd0de14b","n":353,"o":"353-1","u":"Définition","t":"Connaître la définition du suicide, du suicidé, du suicidant, du suicidaire","q":"Comment caractérise-t-on une personne 'suicidaire' ?","a":"<p>Une personne <strong>suicidaire</strong> est un individu ayant ou exprimant, verbalement ou non, des <strong>idées suicidaires</strong>.</p>"},{"i":"37373f1543b3","n":353,"o":"353-1","u":"Définition","t":"Connaître la définition du suicide, du suicidé, du suicidant, du suicidaire","q":"Comment définit-on une personne 'suicidée' et une personne 'suicidante' ?","a":"<ul><li>Une personne <strong>suicidée</strong> est une personne qui s'est donné la mort volontairement.</li><li>Une personne <strong>suicidante</strong> est un individu ayant <strong>survécu à une tentative de suicide (TS)</strong>.</li></ul>"},{"i":"a89a23052014","n":353,"o":"353-1","u":"Définition","t":"Connaître la définition du suicide, du suicidé, du suicidant, du suicidaire","q":"Quelle est la définition du suicide, selon la terminologie médicale ?","a":"<p>Le <strong>suicide</strong> est un acte <strong>délibéré</strong> de mettre fin à sa propre vie, on parle de suicide « <strong>abouti</strong> ».</p>"},{"i":"1744e3c39325","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Décrivez l'épidémiologie du suicide concernant le sexe et l'âge en France.","a":"<ul><li><strong>Sexe</strong> : Il existe une <strong>surmortalité masculine nette</strong>, avec un ratio d'environ <strong>3 hommes pour 1 femme</strong>.</li><li><strong>Âge</strong> : Le taux de suicide <strong>augmente avec l'âge</strong>. Il est <strong>rare chez l'adolescent</strong> mais <strong>fréquent chez l'homme âgé</strong>.</li></ul>"},{"i":"3b2f16b6c6cf","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Quel est l'ordre de grandeur de l'incidence annuelle du suicide en France et quels sont les chiffres clés associés ?","a":"<p>En France, l'incidence annuelle du suicide est d'environ <strong>9 000 cas/an</strong>, soit <strong>6 pour 100 000 habitants/an</strong>. Cela représente environ <strong>1 suicide toutes les 40 minutes</strong>.</p>"},{"i":"6d6a8b531b42","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Quelle est l'incidence annuelle des tentatives de suicide (TS) avec contact du système de soins en France ?","a":"<p>Il y a entre <strong>150 000 et 200 000 tentatives de suicide par an</strong> en France avec contact des services de soins, soit environ <strong>1 tentative de suicide toutes les 4 minutes</strong>.</p>"},{"i":"91b5d004c185","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Quelle est la principale cause de mortalité du suicide en fonction des tranches d'âge en France ?","a":"<ul><li>Le suicide est la <strong>1<sup>ère</sup> cause de mortalité</strong> chez les <strong>25-35 ans</strong>.</li><li>C'est la <strong>2<sup>ème</sup> cause de mortalité</strong> chez les <strong>15-25 ans</strong>.</li></ul>"},{"i":"c984fce34df9","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Décrivez l'épidémiologie des idées suicidaires chez les adultes et les adolescents, incluant la prédominance sexuelle.","a":"<ul><li>Chez les <strong>adultes (18-85 ans)</strong>, <strong>4,2%</strong> ont pensé au suicide au cours des 12 derniers mois.</li><li>Chez les <strong>adolescents</strong>, cette proportion est de <strong>5 à 10%</strong> sur les 12 derniers mois, avec une <strong>prédominance féminine nette</strong> (environ 2 filles pour 1 garçon).</li></ul>"},{"i":"d3e8ad5fefa4","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Quelle est la prévalence de la tentative de suicide au cours de la vie et sur les 12 derniers mois dans la population adulte ?","a":"<ul><li>La prévalence de la tentative de suicide au cours de la vie est de <strong>7,2%</strong> chez les adultes.</li><li>Sur les 12 derniers mois, cette prévalence est de <strong>0,4%</strong>.</li></ul>"},{"i":"eec13def9ce4","n":353,"o":"353-2","u":"Epidémiologie","t":"Connaître l’épidémiologie des suicides et tentatives de suicide, des idées suicidaires selon l’âge et le sexe","q":"Quelles sont les données épidémiologiques concernant la récidive et le pronostic des tentatives de suicide (TS) ?","a":"<ul><li>Environ <strong>40% des tentatives de suicide récidivent</strong>, dont la moitié survient dans l'année.</li><li>La <strong>mortalité par suicide l'année suivant une TS est de 1%</strong> (soit 50 fois plus que dans la population générale).</li><li>Approximativement <strong>10% des sujets</strong> ayant fait une TS décéderont par suicide au cours de leur vie.</li></ul>"},{"i":"1e96034d5488","n":353,"o":"353-3","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une crise suicidaire","q":"Qu'est-ce que le syndrome présuicidaire de Ringel et quels signes doivent faire évoquer un risque imminent de passage à l'acte ?","a":"<p>Le syndrome présuicidaire de Ringel regroupe les signes faisant évoquer un risque imminent de passage à l'acte :</p><ul><li><strong>Comportements préparatoires</strong> : rédaction de lettres, dispositions testamentaires, dons.</li><li>L'<strong>ACALMIE</strong> : calme apparent, attitude de retrait, effondrement de la réactivité émotionnelle et affective, de l'agressivité et des échanges interpersonnels. Cette accalmie est trompeuse, elle précède le passage à l'acte et ne signe pas une amélioration.</li></ul>"},{"i":"25c3025b5536","n":353,"o":"353-3","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une crise suicidaire","q":"Comment doit-on aborder la question des idées suicidaires chez un patient ?","a":"<p>Il faut <strong>toujours interroger directement le patient</strong> sur l'existence d'idées de suicide. Cela ne les fait pas émerger et favorise leur expression et la prise en charge.</p>"},{"i":"38a371f64fc7","n":353,"o":"353-3","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une crise suicidaire","q":"Quels sont les signes cliniques souvent peu spécifiques d'une crise suicidaire ?","a":"<p>Les manifestations cliniques, souvent peu spécifiques, comprennent :</p><ul><li>Symptômes dépressifs ou anxieux non spécifiques.</li><li><strong>Isolement</strong>, retrait des marques d'affection et du contact physique.</li><li>Prises de risque inconsidérées, consommation de substances psychoactives.</li><li>Idées et comportements préoccupants : <strong>sentiment de désespoir</strong>, souffrance psychique intense, réduction du sens des valeurs, cynisme, goût pour le morbide, recherche soudaine de moyens létaux.</li></ul>"},{"i":"3e356b08a6c7","n":353,"o":"353-3","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une crise suicidaire","q":"Quelle est la définition d'une crise suicidaire ?","a":"<p>La crise suicidaire est une <strong>crise psychique</strong>, survenant dans un contexte de vulnérabilité, caractérisée par l'émergence et l'expression d'<strong>idées suicidaires</strong>. C'est un état <strong>réversible et temporaire</strong>, dont le risque majeur est le suicide.</p>"},{"i":"d11bcc699f12","n":353,"o":"353-3","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une crise suicidaire","q":"Comment survient une crise suicidaire, selon le mécanisme progressif décrit ?","a":"<p>La crise suicidaire survient lorsque les <strong>ressources adaptatives sont épuisées</strong>. Le processus est progressif :</p><ul><li><strong>Phase initiale</strong> : la personne en détresse explore des alternatives.</li><li><strong>Échec progressif</strong> : chaque solution échouant réduit les options perçues.</li><li><strong>Accumulation des échecs</strong> : le sentiment d'impasse se renforce et les idées suicidaires deviennent centrales.</li><li><strong>Phase critique</strong> : si toutes les alternatives perçues échouent, le suicide apparaît comme la seule issue.</li></ul>"},{"i":"4af4e3c0eac0","n":353,"o":"353-4","u":"Diagnostic positif","t":"Connaître les formes cliniques selon l’âge","q":"Quels sont les signes d'une crise suicidaire chez l'enfant de 5-6 ans et plus ?","a":"<p>Chez l'enfant, la crise suicidaire peut se manifester par des signes aspécifiques et spécifiques :</p><ul><li>Signes aspécifiques : <strong>irritabilité</strong>, <strong>agitation</strong>, <strong>repli</strong>, <strong>isolement</strong>, <strong>baisse des résultats scolaires</strong>, <strong>régression développementale</strong> (encoprésie, énurésie secondaires), <strong>plaintes physiques</strong> (douleurs, céphalées, maux de ventre).</li><li>Signes spécifiques : <strong>préoccupations exagérées pour la mort</strong>, <strong>blessures à répétition</strong> ou comportements de mise en danger à dimension suicidaire.</li><li>Moyens utilisés : <strong>pendaison/strangulation</strong>, <strong>défenestration</strong>.</li></ul>"},{"i":"a0355340a1d5","n":353,"o":"353-4","u":"Diagnostic positif","t":"Connaître les formes cliniques selon l’âge","q":"Comment se manifeste la crise suicidaire chez l'adolescent ?","a":"<p>Chez l'adolescent, la crise suicidaire peut se manifester par :</p><ul><li>Une <strong>baisse des résultats scolaires</strong>.</li><li>Une <strong>attirance pour la marginalité</strong>.</li><li>Des <strong>fugues</strong>.</li><li>Des conduites d'<strong>anorexie ou de boulimie</strong>.</li><li>Des <strong>conduites addictives</strong>.</li><li>Des <strong>prises de risque</strong> (notamment sexuel).</li><li>Des <strong>conduites ordaliques</strong> (remettre sa survie au hasard).</li><li>Le moyen le plus fréquent est l'<strong>intoxication médicamenteuse</strong> (80% des cas, psychotropes surtout).</li></ul>"},{"i":"c4c6e767ca01","n":353,"o":"353-4","u":"Diagnostic positif","t":"Connaître les formes cliniques selon l’âge","q":"Quels sont les signes d'augmentation du risque suicidaire chez un patient avec un trouble psychiatrique ?","a":"<p>Chez un patient avec un trouble psychiatrique, l'augmentation du risque suicidaire doit être évaluée en permanence et peut se manifester par :</p><ul><li>Un <strong>isolement avec rupture</strong> des contacts habituels.</li><li>L'<strong>abandon des activités habituelles</strong>.</li><li>L'<strong>exacerbation des symptômes psychiatriques</strong>.</li></ul>"},{"i":"d6c27aaabe9a","n":353,"o":"353-4","u":"Diagnostic positif","t":"Connaître les formes cliniques selon l’âge","q":"Comment peut se présenter la crise suicidaire chez l'adulte et le sujet âgé ?","a":"<p>Chez l'adulte, les signes peuvent être :</p><ul><li>Idées suicidaires peu exprimées ou manifestes.</li><li><strong>Ennui</strong>, sentiment de perte de rôle, d'échec, d'injustice.</li><li><strong>Arrêts de travail à répétition</strong> ou surinvestissement professionnel.</li><li><strong>Consultations répétées pour symptômes aspécifiques</strong>.</li><li>Difficultés relationnelles et conjugales.<p>Chez le sujet âgé, les manifestations sont souvent moins explicites :</p></li><li>Idées suicidaires rarement exprimées (mais jamais à banaliser).</li><li><strong>Repli sur soi</strong>.</li><li><strong>Perte d'intérêt pour les activités</strong>.</li><li><strong>Refus de s'alimenter</strong>.</li><li><strong>Refus de soin</strong>.</li></ul>"},{"i":"730bb41c1dc1","n":353,"o":"353-5","u":"Diagnostic positif","t":"Savoir évaluer le risque, l’urgence et la dangerosité (RUD) à tous les âges de la vie","q":"Quels sont les critères d'une urgence suicidaire « élevée » dans l'évaluation de la crise suicidaire ?","a":"<p>Une urgence suicidaire est qualifiée d'« <strong>élevée</strong> » en présence des critères suivants :</p><ul><li><strong>Isolement :</strong> très isolé.</li><li><strong>Communication :</strong> agitation ou ralentissement majeur, souffrance omniprésente ou totalement tue, refus des soins.</li><li><strong>Alternatives :</strong> idées envahissantes, ruminations anxieuses, ne voit pas d'autre recours.</li><li><strong>Scénario :</strong> accès direct et immédiat à un moyen létal.</li><li><strong>Décision :</strong> passage à l'acte planifié et prévu dans les jours qui viennent.</li><li><strong>État psychologique :</strong> coupé de ses émotions (rationalise) ou très agité/anxieux.</li></ul>"},{"i":"9f90fa778ad3","n":353,"o":"353-5","u":"Diagnostic positif","t":"Savoir évaluer le risque, l’urgence et la dangerosité (RUD) à tous les âges de la vie","q":"Comment évalue-t-on la dangerosité (le D de RUD) dans la conduite suicidaire ?","a":"<p>L'évaluation de la dangerosité repose sur l'appréciation des <strong>moyens à disposition</strong> du patient selon leur <strong>létalité potentielle</strong> et leur <strong>accessibilité immédiate</strong>, graduée en faible, moyenne ou élevée.</p><ul><li><strong>Dangerosité faible :</strong> l'absence d'accès immédiat au moyen létal (ex: vouloir se suicider par arme à feu sans en posséder) laisse une possibilité d'intervention.</li><li><strong>Dangerosité élevée :</strong> présence d'un moyen létal immédiatement accessible et connaissance de son utilisation (ex: intoxication médicamenteuse volontaire avec connaissances médicales et accès direct aux médicaments).</li></ul><p>La <strong>sécurisation immédiate des moyens létaux</strong> (retrait des armes, restriction d'accès aux médicaments) est une étape essentielle de l'évaluation.</p>"},{"i":"c7adfa642b41","n":353,"o":"353-5","u":"Diagnostic positif","t":"Savoir évaluer le risque, l’urgence et la dangerosité (RUD) à tous les âges de la vie","q":"Comment évalue-t-on le risque suicidaire selon l'échelle RUD chez un patient ?","a":"<p>L'évaluation du risque suicidaire (le R de RUD) repose sur la recherche des <strong>facteurs de risque</strong> et des <strong>facteurs protecteurs</strong>.</p><ul><li><strong>Facteurs de risque individuels :</strong> expression d'idées suicidaires, antécédents personnels de tentative de suicide (TS), trouble psychiatrique, consommation de toxiques, trouble de la personnalité (impulsivité, désespoir), sexe masculin.</li><li><strong>Facteurs de risque familiaux :</strong> antécédents familiaux de TS, de suicide, de maladie psychiatrique, d'addiction.</li><li><strong>Facteurs de risque psychosociaux :</strong> difficultés économiques/professionnelles, isolement social, séparation, événements humiliants, maltraitance infantile, appartenance LGBT.</li><li><strong>Facteurs protecteurs :</strong> résilience individuelle, soutien socio-familial, avoir des enfants, croyances religieuses.</li></ul>"},{"i":"24c8a7487e4f","n":353,"o":"353-8","u":"Prise en charge","t":"Connaître la conduite à tenir en urgence","q":"Quel traitement médicamenteux est à privilégier en cas d'impulsivité importante chez un patient suicidaire ?","a":"<p>En cas d'impulsivité importante, il faut <strong>éviter une première prescription de benzodiazépine</strong> en raison d'un effet désinhibiteur possible. Il est préférable de privilégier un <strong>antipsychotique sédatif de type phénothiazine</strong> (par exemple, la <strong>cyamémazine</strong>).</p>"},{"i":"4c461a339e83","n":353,"o":"353-8","u":"Prise en charge","t":"Connaître la conduite à tenir en urgence","q":"Quelle doit être la hiérarchisation de la prise en charge d'un patient suicidaire ou suicidant en urgence ?","a":"<p>La prise en charge doit hiérarchiser le <strong>somatique</strong> puis le <strong>psychiatrique</strong>. Le bilan somatique doit être complet et les atteintes traitées avant toute considération psychiatrique.</p>"},{"i":"74e60a67b5a1","n":353,"o":"353-8","u":"Prise en charge","t":"Connaître la conduite à tenir en urgence","q":"Quand l'avis psychiatrique doit-il être sollicité pour un patient suicidaire ou suicidant en urgence ?","a":"<p>L'avis psychiatrique doit être systématiquement sollicité pour tout patient suicidaire ou suicidant, mais seulement <strong>après la stabilisation de son état clinique non psychiatrique</strong>.</p>"},{"i":"9ec408863fbb","n":353,"o":"353-8","u":"Prise en charge","t":"Connaître la conduite à tenir en urgence","q":"Quel est le risque persistant en matière de suicide même en cas d'hospitalisation d'un patient suicidaire ?","a":"<p>Il est important de retenir que l'hospitalisation <strong>ne prévient pas tous les suicides</strong> ; environ <strong>5 %</strong> surviennent en établissement de soins. Les causes principales sont la <strong>défenestration/précipitation</strong> et la <strong>pendaison</strong>.</p>"},{"i":"ea77cc21c658","n":353,"o":"353-8","u":"Prise en charge","t":"Connaître la conduite à tenir en urgence","q":"Quels sont les objectifs immédiats de l'hospitalisation d'un patient suicidaire en urgence et les moyens pour y parvenir ?","a":"<p>L'objectif principal est de <strong>protéger le patient en limitant le risque de passage à l'acte</strong>. Les moyens incluent :</p><ul><li>Limiter l'accès aux moyens létaux (inventaire des affaires, retrait des objets dangereux, blocage des fenêtres).</li><li>Assurer une surveillance rapprochée (chambre à proximité de l'infirmerie, voire surveillance à vue permanente).</li></ul>"}]};